function Overview({ openConnections }: { openConnections: () => void }) {
  const { copy, notify } = useExperience(); const [period, setPeriod] = useState("Aug 12–18");
  return <div className="view-wrap"><AppHeader title={copy("Portfolio overview", "Resumen del portafolio")} subtitle={copy("A calm, live read on leasing, cash, and service.", "Una lectura clara y en vivo de arrendamiento, caja y servicio.")} actions={<><details className="app-menu"><summary className="soft-button"><Calendar width={18} height={18}/>{period}<NavArrowDown width={16} height={16}/></summary><div className="menu-popover">{["Aug 12–18", "Aug 5–11", "July 2026"].map((item) => <button key={item} onClick={() => setPeriod(item)}><Check className={period === item ? "visible-check" : "hidden-check"} width={15} height={15}/>{item}</button>)}</div></details><button className="primary-button" onClick={openConnections}><NetworkLeft width={18} height={18}/>{copy("Connect data", "Conectar datos")}</button></>}/><section className="overview-intro" data-reveal><div><span className="presence-dot"/>{copy("Updated 4 minutes ago", "Actualizado hace 4 minutos")}</div><p>{copy("142 units across 6 properties", "142 unidades en 6 propiedades")}</p></section><section className="metric-grid">{metrics.map((metric) => <article className="metric-card" data-reveal data-sound-reveal key={metric.label[0]}><div className="metric-top"><span>{copy(...metric.label)}</span><StatsUpSquare width={18} height={18}/></div><strong><AnimatedNumber value={metric.value} prefix={metric.prefix} suffix={metric.suffix} decimals={metric.decimals}/></strong><div className="metric-meta"><span>{metric.delta}</span> {copy(...metric.detail)}</div><div className="mini-bars" aria-hidden="true">{metric.bars.map((height, index) => <i key={index} style={{ "--bar-height": `${height}%`, "--bar-delay": `${index * 65}ms` } as React.CSSProperties}/>)}</div></article>)}</section><section className="overview-grid" data-reveal><article className="panel funnel-panel"><div className="panel-heading"><div><p className="eyebrow">{copy("Leasing", "Arrendamiento")}</p><h2>{copy("Lead-to-lease funnel", "Embudo de prospecto a contrato")}</h2></div><span className="quiet-label">{period}</span></div><div className="funnel-stage-labels">{stages.map((stage) => <div key={stage.label[0]}><strong><AnimatedNumber value={stage.value}/></strong><span>{copy(...stage.label)}</span></div>)}</div><div className="funnel-graphic">{stages.map((stage, index) => <div className="funnel-band" style={{ "--band-width": stage.width, "--band-delay": `${index * 110}ms` } as React.CSSProperties} key={stage.label[0]}/>)}</div><div className="funnel-footer"><span><strong>55.4%</strong> contacted → viewed</span><span><strong>14.2%</strong> contacted → signed</span><button className="text-button" onClick={openConnections}>{copy("Configure source", "Configurar fuente")}<NavArrowRight width={16} height={16}/></button></div></article><article className="panel coverage-panel"><div className="panel-heading"><div><p className="eyebrow">{copy("Data coverage", "Cobertura de datos")}</p><h2>{copy("Two sources unlock the view", "Dos fuentes activan la vista")}</h2></div><ShieldCheck width={22} height={22}/></div>{[["quickbooks", "Accounting", "QuickBooks or Xero"], ["appfolio", "Leasing pipeline", "AppFolio, Buildium, or PMS"], ["whatsapp", "Resident channels", "Messages, email, and calls"]].map(([provider, label, detail], index) => <div className="source-row" key={provider}><BrandMark provider={provider} small/><div><strong>{label}</strong><span>{detail}</span></div><span className={`status-pill ${index === 2 ? "optional" : ""}`}>{index === 2 ? copy("Optional", "Opcional") : copy("Required", "Requerido")}</span></div>)}<button className="wide-button" onClick={openConnections}>{copy("Open connections", "Abrir conexiones")}<NavArrowRight width={17} height={17}/></button></article></section><section className="panel activity-panel" data-reveal><div className="panel-heading"><div><p className="eyebrow">Aval, now</p><h2>{copy("Work moving through the system", "Trabajo moviéndose por el sistema")}</h2></div><button className="soft-button" onClick={() => notify(copy("History opened", "Historial abierto"), copy("38 verified actions from this week.", "38 acciones verificadas de esta semana."))}><Archive width={17} height={17}/>{copy("History", "Historial")}</button></div><div className="activity-flow">{[["whatsapp", "Nightly delinquency sweep found 4 accounts past due."], ["slack", "Flags the accounts to the portfolio manager."], ["twilio", "Calls the resident after approval."], ["complete", "Payment plan set up; secure link sent."]].map(([provider, text], index) => <span className="activity-segment" key={provider}>{index > 0 && <i className="flow-arrow">→</i>}<span className={`activity-card ${provider === "complete" ? "complete" : ""}`}><span>{provider === "complete" ? <CheckCircle width={24} height={24}/> : <BrandMark provider={provider} small/>}</span><p>{text}</p></span></span>)}</div></section></div>;
}

