const columns = [{ id: "needs", label: ["Needs you", "Te necesita"] as Pair, icon: User }, { id: "progress", label: ["In progress", "En progreso"] as Pair, icon: Clock }, { id: "parked", label: ["Parked", "En espera"] as Pair, icon: Pause }, { id: "done", label: ["Done", "Listo"] as Pair, icon: CheckCircle }];
function TasksView() {
  const { copy, notify, celebrate } = useExperience(); const [layout, setLayout] = useState<"board" | "list">("board"); const [query, setQuery] = useState(""); const [filter, setFilter] = useState("all"); const [items, setItems] = useState(initialTasks); const [editing, setEditing] = useState<Task | null>(null); const [creating, setCreating] = useState(false); const [draft, setDraft] = useState("");
  const visible = items.filter((task) => (filter === "all" || task.status === filter) && `${task.title} ${task.detail}`.toLowerCase().includes(query.toLowerCase()));
  const saveTask = (event: FormEvent) => { event.preventDefault(); if (!draft.trim()) return; setItems((current) => [{ id: Date.now(), status: "needs", title: draft.trim(), detail: "Created by Camila · just now", provider: "slack", time: "Now", action: "Review" }, ...current]); notify(copy("Task created", "Tarea creada"), draft); setDraft(""); setCreating(false); };
  const complete = (task: Task) => { setItems((current) => current.map((item) => item.id === task.id ? { ...item, status: "done", action: "Complete", time: "Now" } : item)); setEditing(null); celebrate(copy("Task complete", "Tarea completada"), task.title); };
  return <div className="view-wrap task-view"><AppHeader title={copy("Tasks", "Tareas")} subtitle={copy("Everything Aval is doing, waiting on, or has finished.", "Todo lo que Aval está haciendo, esperando o ya terminó.")} actions={<><div className="segmented compact"><button className={layout === "list" ? "active" : ""} onClick={() => setLayout("list")} aria-label="List"><ViewColumns3 width={18} height={18}/></button><button className={layout === "board" ? "active" : ""} onClick={() => setLayout("board")} aria-label="Board"><ViewGrid width={18} height={18}/></button></div><button className="primary-button" onClick={() => setCreating(true)}><Plus width={18} height={18}/>{copy("New task", "Nueva tarea")}</button></>}/><div className="task-toolbar"><label className="search-field"><Search width={19} height={19}/><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={copy("Search tasks", "Buscar tareas")}/></label><details className="app-menu"><summary className="soft-button"><FilterList width={17} height={17}/>{copy("Filters", "Filtros")}<NavArrowDown width={15} height={15}/></summary><div className="menu-popover">{[{ id: "all", label: copy("All tasks", "Todas") }, ...columns.map((column) => ({ id: column.id, label: copy(...column.label) }))].map((option) => <button key={option.id} onClick={() => setFilter(option.id)}><Check className={filter === option.id ? "visible-check" : "hidden-check"} width={15} height={15}/>{option.label}</button>)}</div></details></div><div className={`task-board ${layout}`}>{columns.map((column) => { const Icon = column.icon; const columnTasks = visible.filter((task) => task.status === column.id); return <section className="task-column" data-reveal key={column.id}><div className="column-heading"><span><Icon width={20} height={20}/>{copy(...column.label)}</span><b>{columnTasks.length}</b></div><div className="column-list">{columnTasks.length ? columnTasks.map((task) => <article className="task-card" key={task.id}><div className="task-card-top"><BrandMark provider={task.provider} small/><span>{task.time}</span></div><h3>{task.title}</h3><p>{task.detail}</p><div className="task-card-bottom"><span>{task.action}</span><button onClick={() => setEditing(task)} aria-label="Open task"><NavArrowRight width={17} height={17}/></button></div></article>) : <div className="empty-column">{copy("Nothing here", "Nada aquí")}</div>}</div></section>; })}</div><Dialog.Root open={creating} onOpenChange={setCreating}><Dialog.Portal><Dialog.Overlay className="dialog-overlay"/><Dialog.Content className="small-dialog"><Dialog.Title>{copy("Create task", "Crear tarea")}</Dialog.Title><form onSubmit={saveTask}><label>{copy("What needs to happen?", "¿Qué debe pasar?")}<textarea autoFocus value={draft} onChange={(event) => setDraft(event.target.value)} placeholder={copy("Describe the outcome…", "Describe el resultado…")}/></label><div className="dialog-actions"><Dialog.Close className="soft-button">{copy("Cancel", "Cancelar")}</Dialog.Close><button className="primary-button" type="submit">{copy("Create task", "Crear tarea")}</button></div></form></Dialog.Content></Dialog.Portal></Dialog.Root><Dialog.Root open={Boolean(editing)} onOpenChange={(open) => !open && setEditing(null)}><Dialog.Portal><Dialog.Overlay className="dialog-overlay"/><Dialog.Content className="small-dialog">{editing && <><div className="dialog-top"><BrandMark provider={editing.provider}/><Dialog.Close className="icon-button"><Xmark width={20} height={20}/></Dialog.Close></div><Dialog.Title>{editing.title}</Dialog.Title><Dialog.Description>{editing.detail}</Dialog.Description><div className="task-detail-meta"><span>{editing.time}</span><span>{editing.action}</span></div><div className="dialog-actions"><button className="soft-button" onClick={() => { notify(copy("Task parked", "Tarea en espera")); setEditing(null); }}>{copy("Park", "Esperar")}</button><button className="primary-button" onClick={() => complete(editing)}><Check width={17} height={17}/>{copy("Mark complete", "Marcar lista")}</button></div></>}</Dialog.Content></Dialog.Portal></Dialog.Root></div>;
}

