function ConnectionDialog({ provider, onClose, onRefresh }: { provider: Provider | null; onClose: () => void; onRefresh: () => void }) {
  const { copy, celebrate, notify } = useExperience(); const [credentials, setCredentials] = useState<Record<string, string>>({}); const [status, setStatus] = useState<"idle" | "working" | "error" | "saved">("idle"); const [message, setMessage] = useState("");
  if (!provider) return null; const providerGuide = guides[provider.id] ?? { aval: ["Secure provider adapter"], customer: ["Administrator consent"], proof: "The upstream identity is verified before sync." }; const blocked = provider.authMode === "oauth2" && provider.configured === false;
  const connect = async (event?: FormEvent) => { event?.preventDefault(); setStatus("working"); setMessage(""); try { const response = await fetch("/api/integrations/connect", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ provider: provider.id, credentials: provider.authMode === "oauth2" ? undefined : credentials, returnTo: `/?view=connections&connected=${provider.id}` }) }); const data = await response.json() as { authorizationUrl?: string; error?: string; required?: string[]; missing?: string[]; connection?: { id: string } }; if (!response.ok) throw new Error(`${data.error ?? "Connection failed"}${data.required ? `: ${data.required.join(", ")}` : ""}${data.missing ? `: ${data.missing.join(", ")}` : ""}`); if (data.authorizationUrl) { window.location.href = data.authorizationUrl; return; } if (!data.connection?.id) throw new Error("Encrypted connection was not returned."); const verification = await fetch("/api/integrations/verify", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ connectionId: data.connection.id }) }); const verified = await verification.json() as { error?: string; connection?: { externalAccountName?: string } }; if (!verification.ok) { setStatus("saved"); setMessage(`${copy("Credentials encrypted. Provider action remains:", "Credenciales cifradas. Falta acción del proveedor:")} ${verified.error ?? provider.note}`); notify(copy("Setup saved", "Configuración guardada"), provider.title); onRefresh(); return; } setStatus("saved"); setMessage(copy("Identity verified. Initial sync is queued.", "Identidad verificada. Sincronización en cola.")); celebrate(copy("Connection verified", "Conexión verificada"), verified.connection?.externalAccountName ?? provider.title); onRefresh(); } catch (error) { setStatus("error"); setMessage(error instanceof Error ? error.message : "Connection failed"); } };
  return <Dialog.Root open onOpenChange={(open) => !open && onClose()}><Dialog.Portal><Dialog.Overlay className="dialog-overlay"/><Dialog.Content className="connection-dialog"><div className="dialog-top"><BrandMark provider={provider.id}/><Dialog.Close className="icon-button"><Xmark width={20} height={20}/></Dialog.Close></div><Dialog.Title>{provider.title}</Dialog.Title><Dialog.Description>{provider.description}</Dialog.Description><div className="dialog-status-row"><span><ShieldCheck width={16} height={16}/>{provider.readOnly ? copy("Read access", "Acceso de lectura") : copy("Two-way channel", "Canal de dos vías")}</span><span><Key width={16} height={16}/>{provider.authMode.replace("_", " ")}</span><span><NetworkLeft width={16} height={16}/>{provider.webhook ? "Webhook + sync" : copy("Scheduled sync", "Sincronización programada")}</span></div><Tabs.Root defaultValue="readiness"><Tabs.List className="dialog-tabs three"><Tabs.Trigger value="readiness">{copy("Readiness", "Preparación")}</Tabs.Trigger><Tabs.Trigger value="access">{copy("Access", "Acceso")}</Tabs.Trigger><Tabs.Trigger value="flow">{copy("Flow", "Flujo")}</Tabs.Trigger></Tabs.List><Tabs.Content value="readiness"><div className="readiness-grid"><div><p>{copy("Aval configures once", "Aval configura una vez")}</p>{providerGuide.aval.map((item) => <span key={item}><Check width={15} height={15}/>{item}</span>)}</div><div><p>{copy("Customer brings", "El cliente aporta")}</p>{providerGuide.customer.map((item) => <span key={item}><User width={15} height={15}/>{item}</span>)}</div></div><p className="proof-note"><ShieldCheck width={16} height={16}/>{providerGuide.proof}</p>{blocked && <div className="setup-warning"><strong>{copy("Aval setup required before customers can connect", "Aval debe configurarse antes de conectar clientes")}</strong><span>{provider.env.join(" · ")}</span></div>}</Tabs.Content><Tabs.Content value="access"><div className="permission-box"><p>{copy("Aval will request", "Aval solicitará")}</p>{provider.permissions.map((permission) => <span key={permission}><Check width={16} height={16}/>{permission}</span>)}</div><p className="connection-note">{provider.note}</p></Tabs.Content><Tabs.Content value="flow"><ol className="architecture-list"><li><b>01</b><span><strong>{copy("Authorize", "Autorizar")}</strong>{copy("Consent is scoped to this workspace.", "El consentimiento se limita a este espacio.")}</span></li><li><b>02</b><span><strong>{copy("Verify", "Verificar")}</strong>{copy("Aval tests the actual upstream identity.", "Aval comprueba la identidad real.")}</span></li><li><b>03</b><span><strong>{copy("Normalize", "Normalizar")}</strong>{copy("Source IDs and timestamps remain traceable.", "Los IDs y fechas quedan rastreables.")}</span></li></ol></Tabs.Content></Tabs.Root>{provider.authMode !== "oauth2" && <form className="credential-form" onSubmit={connect}>{provider.credentialFields?.map((field) => <label key={field.key}>{field.label}<input type={field.secret ? "password" : "text"} value={credentials[field.key] ?? ""} onChange={(event) => setCredentials((current) => ({ ...current, [field.key]: event.target.value }))} autoComplete="off" required/></label>)}</form>}{message && <p className={`dialog-message ${status}`}>{message}</p>}<div className="dialog-actions"><button className="soft-button" onClick={onClose}>{copy("Cancel", "Cancelar")}</button><button className="primary-button" disabled={status === "working" || status === "saved" || blocked} onClick={() => connect()}>{status === "working" ? copy("Verifying…", "Verificando…") : status === "saved" ? copy("Saved", "Guardado") : blocked ? copy("Aval setup required", "Aval requiere configuración") : provider.authMode === "oauth2" ? copy("Continue to authorization", "Continuar a autorización") : copy("Encrypt & verify", "Cifrar y verificar")}<NavArrowRight width={17} height={17}/></button></div></Dialog.Content></Dialog.Portal></Dialog.Root>;
}

function DesktopApp() {
  const { copy, locale, setLocale, theme, setTheme, sounds, setSounds, celebrate } = useExperience(); const [view, setView] = useState<View>(() => { if (typeof window === "undefined") return "overview"; const requested = new URLSearchParams(window.location.search).get("view") as View | null; return requested && navGroups.some((group) => group.items.some((item) => item.id === requested)) ? requested : "overview"; }); const [providers, setProviders] = useState<Provider[]>(fallbackProviders); const [loading, setLoading] = useState(true); const [selectedProvider, setSelectedProvider] = useState<Provider | null>(null); const [collapsed, setCollapsed] = useState(false); const [profile, setProfile] = useState(false); const [notifications, setNotifications] = useState(false); const [notificationCount, setNotificationCount] = useState(3);
  const loadProviders = async () => { try { const response = await fetch("/api/integrations"); const data = await response.json() as { providers?: Provider[] }; if (data.providers?.length) setProviders(data.providers); } catch { /* local preview stays usable */ } setLoading(false); };
  useEffect(() => { queueMicrotask(() => void loadProviders()); const show = () => setNotifications(true); window.addEventListener("aval:notifications", show); const connected = new URLSearchParams(window.location.search).get("connected"); if (connected) { window.setTimeout(() => celebrate(copy("Connection authorized", "Conexión autorizada"), connected), 250); const url = new URL(window.location.href); url.searchParams.delete("connected"); window.history.replaceState({}, "", url); } return () => window.removeEventListener("aval:notifications", show); }, []); // eslint-disable-line react-hooks/exhaustive-deps
  const setActiveView = (next: View) => { setView(next); setProfile(false); const url = new URL(window.location.href); url.searchParams.set("view", next); window.history.replaceState({}, "", url); window.scrollTo({ top: 0, behavior: "smooth" }); }; const openConnections = () => setActiveView("connections"); const openProvider = (id: string) => setSelectedProvider(providers.find((provider) => provider.id === id) ?? null); const title = useMemo<Pair>(() => navGroups.flatMap((group) => group.items).find((item) => item.id === view)?.label ?? ["Aval", "Aval"], [view]);
  return <main className={`app-shell ${collapsed ? "sidebar-is-collapsed" : ""}`}><aside className="sidebar"><div className="brand-lockup"><span className="brand-symbol">a</span><div><strong>aval</strong><small>{copy("Property operations", "Operaciones inmobiliarias")}</small></div><button className="icon-button sidebar-collapse" onClick={() => setCollapsed(!collapsed)} aria-label="Collapse sidebar"><ViewColumns3 width={18} height={18}/></button></div><nav>{navGroups.map((group) => <div className="nav-group" key={group.label[0]}><p>{copy(...group.label)}</p>{group.items.map((item) => { const Icon = item.icon; return <button className={view === item.id ? "active" : ""} onClick={() => setActiveView(item.id)} key={item.id} title={copy(...item.label)}><Icon width={20} height={20}/><span>{copy(...item.label)}</span>{item.count && <b>{item.count}</b>}{view === item.id && <NavArrowRight className="nav-chevron" width={16} height={16}/>}</button>; })}</div>)}</nav><button className="workspace-card" onClick={() => setProfile(!profile)}><span className="initials">AC</span><span><strong>Acme Residential</strong><small>Camila Reyes</small></span><span className="icon-button"><NavArrowDown width={16} height={16}/></span></button>{profile && <div className="profile-menu"><div><span className="initials">CR</span><span><strong>Camila Reyes</strong><small>Administrator</small></span></div><button onClick={() => setActiveView("settings")}><Settings width={17} height={17}/>{copy("Profile & settings", "Perfil y ajustes")}</button><button onClick={() => setLocale(locale === "en" ? "latam" : "en")}><Language width={17} height={17}/>{locale === "en" ? "Español LatAm" : "English"}</button><button onClick={() => setTheme(theme === "light" ? "dark" : "light")}>{theme === "light" ? <HalfMoon width={17} height={17}/> : <SunLight width={17} height={17}/>} {theme === "light" ? copy("Dark mode", "Modo oscuro") : copy("Light mode", "Modo claro")}</button><button onClick={() => setSounds(!sounds)}>{sounds ? <SoundHigh width={17} height={17}/> : <SoundOff width={17} height={17}/>} {sounds ? copy("Sounds on", "Sonidos activos") : copy("Sounds off", "Sonidos apagados")}</button><a href="/mobile"><SmartphoneDevice width={17} height={17}/>{copy("Open mobile app", "Abrir app móvil")}</a><a href="/signout-with-chatgpt?return_to=/"><LogOut width={17} height={17}/>{copy("Sign out", "Cerrar sesión")}</a></div>}</aside><section className="content-shell" aria-label={copy(...title)}>{view === "overview" && <Overview openConnections={openConnections}/>} {view === "tasks" && <TasksView/>} {view === "inbox" && <InboxView/>} {view === "connections" && <ConnectionsView providers={providers} loading={loading} onOpen={openProvider}/>} {view === "settings" && <SettingsView openConnections={openConnections}/>} {(["properties", "leasing", "maintenance", "accounting", "documents"] as View[]).includes(view) && <OperationsView view={view} openConnections={openConnections}/>}</section>{selectedProvider && <ConnectionDialog provider={selectedProvider} onClose={() => setSelectedProvider(null)} onRefresh={loadProviders}/>}<Dialog.Root open={notifications} onOpenChange={setNotifications}><Dialog.Portal><Dialog.Overlay className="dialog-overlay subtle"/><Dialog.Content className="notification-drawer"><div className="drawer-heading"><div><p className="eyebrow">{copy("Live workspace", "Espacio en vivo")}</p><Dialog.Title>{copy("Notifications", "Notificaciones")}</Dialog.Title></div><Dialog.Close className="icon-button"><Xmark width={20} height={20}/></Dialog.Close></div><div className="notification-list"><button onClick={() => { setActiveView("tasks"); setNotifications(false); }}><span className="presence-dot"/><span><strong>{copy("Draft needs approval", "Un borrador necesita aprobación")}</strong><small>Diana Ortiz · WhatsApp · 9 min</small></span></button><button onClick={() => { setActiveView("connections"); setNotifications(false); }}><span className="presence-dot"/><span><strong>{copy("Accounting source incomplete", "Fuente contable incompleta")}</strong><small>QuickBooks or Xero · 24 min</small></span></button><button onClick={() => { setActiveView("inbox"); setNotifications(false); }}><span className="presence-dot"/><span><strong>{copy("Two resident replies", "Dos respuestas de residentes")}</strong><small>Shared inbox · 31 min</small></span></button></div><button className="wide-button" onClick={() => setNotificationCount(0)}><Check width={17} height={17}/>{notificationCount ? copy("Mark all as read", "Marcar todo como leído") : copy("All caught up", "Todo al día")}</button></Dialog.Content></Dialog.Portal></Dialog.Root></main>;
}

export default function Home() { return <ExperienceProvider><DesktopApp/></ExperienceProvider>; }
